SELECT m.ProductId,m.SpecificationAttributeOptionId,m.CustomValue,m.AttributeTypeId,m.AllowFiltering,m.ShowOnProductPage,m.DisplayOrder,m.IsPin,m.ShortValue,o.Name AS OptionName,a.Id AS AttributeId,a.Name AS AttributeName,a.NameEn AS AttributeEnglishName,a.Unit,a.SpecificationAttributeGroupId,g.Name AS GroupName FROM Product_SpecificationAttribute_Mapping m JOIN SpecificationAttributeOption o ON o.Id=m.SpecificationAttributeOptionId JOIN SpecificationAttribute a ON a.Id=o.SpecificationAttributeId LEFT JOIN SpecificationAttributeGroup g ON g.Id=a.SpecificationAttributeGroupId WHERE m.ProductId IN (SELECT p.Id FROM Product p WHERE p.Published=1 AND p.Deleted=0 AND p.DisableBuyButton=0 AND p.CallForPrice=0 AND p.VisibleIndividually=1 AND EXISTS(SELECT 1 FROM ProductAttributeCombination pac WHERE pac.ProductId=p.Id AND pac.Deleted=0 AND pac.IsNotExist=0 AND pac.StockAvailabilityTypeId=20 AND pac.StockQuantity>0 AND pac.FinalPrice>0))
